    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return v


def _to_bool(v, default=False):
    if v is None:
        return default
    if isinstance(v, bool):
        return v
    return str(v).strip().lower() in ("1", "true", "yes", "on")


def _pick_url(results, prefer_video=False):
    fallback = None
    for item in results:
        if not isinstance(item, dict):
            continue
        url = str(item.get("url") or "").strip()
        if not url:
            continue
        ot = str(item.get("outputType") or "").lower()
        if not fallback:
            fallback = url
        if prefer_video and ot in VIDEO_TYPES:
            return url
        if (not prefer_video) and (ot in IMAGE_TYPES or ot == ""):
            return url
        if not prefer_video and ot in VIDEO_TYPES:
