import httpx
import base64
import json

API_BASE = "https://www.runninghub.ai/openapi/v2"
QUERY_URL = API_BASE + "/query"
UPLOAD_URL = API_BASE + "/media/upload/binary"
DEFAULT_WORKFLOW_ID = "2103527148329140225"
NON_TERMINAL = ("CREATE", "QUEUED", "RUNNING", "PENDING", "SUBMITTED")
IMAGE_TYPES = ("png", "jpg", "jpeg", "webp", "gif", "bmp")
VIDEO_TYPES = ("mp4", "webm", "mov", "mkv", "avi")


def _pick(ctx, dyn, key, default=None):
    v = ctx.get(key)
    if v is None or (isinstance(v, str) and not v.strip()):
        v = dyn.get(key) if dyn else None
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return v


def _to_bool(v, default=False):
    if v is None:
        return default
    if isinstance(v, bool):
        return v
    return str(v).strip().lower() in ("1", "true", "yes", "on")


def _pick_url(results, prefer_video=False):
    fallback = None
    for item in results:
        if not isinstance(item, dict):
            continue
        url = str(item.get("url") or "").strip()
        if not url:
            continue
        ot = str(item.get("outputType") or "").lower()
        if not fallback:
            fallback = url
        if prefer_video and ot in VIDEO_TYPES:
            return url
        if (not prefer_video) and (ot in IMAGE_TYPES or ot == ""):
            return url
    return fallback


async def _upload(client, api_key, value, idx):
    """参考图三态归一：RunningHub 文件名透传 / data URI 解码上传 / http(s) 取字节上传"""
    v = str(value or "").strip()
    if not v or v == "None":
        return None
    if not (v.startswith("data:") or v.startswith("http")):
        return v
    if v.startswith("data:"):
        raw = base64.b64decode(v.split(",", 1)[1])
        fname = f"image{idx}.png"
        ctype = "image/png"
    else:
        resp = await client.get(v, timeout=120)
        if resp.status_code >= 400:
            raise RuntimeError(f"参考图{idx}下载失败({resp.status_code}): {v[:120]}")
        raw = resp.content
        ctype = resp.headers.get("content-type", "image/png").split(";")[0] or "image/png"
        ext = ctype.split("/")[-1].replace("jpeg", "jpg")
        fname = f"image{idx}.{ext}"
    # 上传只能 Bearer 头：带 Content-Type: application/json 会破坏 multipart 边界
    r = await client.post(
        UPLOAD_URL,
        headers={"Authorization": f"Bearer {api_key}"},
        files={"file": (fname, raw, ctype)},
        timeout=300,
    )
    j = r.json() if r.content else {}
    if not isinstance(j, dict) or j.get("code") != 0:
        raise RuntimeError(f"参考图{idx}上传失败: {(j.get('message') if isinstance(j, dict) else '') or str(j)[:300]}")
    d = j.get("data") or {}
    return d.get("download_url") or d.get("fileName")


async def generate(ctx, api):
    dyn = ctx.get("dynamic_inputs") or {}
    api_key = str(ctx.get("api_key") or "").strip()
    if not api_key and isinstance(api, dict) and callable(api.get("get_api_key")):
        api_key = str(api.get("get_api_key")() or "").strip()
    if not api_key:
        raise RuntimeError("缺少 RunningHub API Key（请在生成源配置里填入 Key 后重试）")
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}

    task_id = str(ctx.get("task_id") or dyn.get("task_id") or "").strip()
    prompt = str(ctx.get("prompt") or dyn.get("prompt") or "").strip()

    async with httpx.AsyncClient(timeout=600) as client:
        # —— 查询分支：单次秒回，绝不 sleep 轮询 ——
        if task_id and not prompt:
            q = await client.post(QUERY_URL, headers=headers, json={"taskId": task_id})
            if q.status_code >= 400:
                raise RuntimeError(f"查询失败({q.status_code}): {q.text[:300]}")
            qj = q.json() or {}
            status = str(qj.get("status") or "").upper()
            if status in NON_TERMINAL:
                return {"url": None, "task_id": task_id, "status": status or "RUNNING"}
            if status == "SUCCESS":
                url = _pick_url(qj.get("results") or [])
                if not url:
                    raise RuntimeError(f"任务成功但无结果URL: {str(qj)[:300]}")
                return {"url": url}
            err = str(qj.get("errorMessage") or "") or str(qj.get("errorCode") or "")
            raise RuntimeError(f"任务失败({status or 'FAILED'}): {err[:300]}")

        # —— 提交分支 ——
        workflow_id = str(_pick(ctx, dyn, "workflow_id", DEFAULT_WORKFLOW_ID)).strip() or DEFAULT_WORKFLOW_ID
        if not workflow_id.isdigit():
            raise ValueError(f"workflow_id 需为纯数字 ID，当前: {workflow_id[:64]}")
        instance_type = str(_pick(ctx, dyn, "instance_type", "default")).strip() or "default"
        if instance_type not in ("default", "plus", "ultra"):
            instance_type = "default"

        # nodeInfoList：显式 JSON 映射为基础
        node_list = []
        raw_nl = str(_pick(ctx, dyn, "node_info_list", "") or "").strip()
        if raw_nl:
            try:
                parsed = json.loads(raw_nl)
            except Exception:
                raise ValueError('node_info_list 需为合法 JSON 数组，如 [{"nodeId":"28","fieldName":"text","fieldValue":"hi"}]')
            if not isinstance(parsed, list):
                raise ValueError("node_info_list 需为 JSON 数组（list）")
            node_list = [n for n in parsed if isinstance(n, dict)]

        # prompt 注入
        prompt_node_id = str(_pick(ctx, dyn, "prompt_node_id", "") or "").strip()
        if prompt:
            if not prompt_node_id:
                if not node_list:
                    raise ValueError("已传入 prompt 但未配置节点映射：请设置 prompt_node_id（prompt 写入的工作流节点 ID，如 28）与 prompt_field_name")
            else:
                pfield = str(_pick(ctx, dyn, "prompt_field_name", "text") or "text").strip() or "text"
                node_list = [n for n in node_list
                             if not (str(n.get("nodeId")) == prompt_node_id and str(n.get("fieldName")) == pfield)]
                node_list.append({"nodeId": prompt_node_id, "fieldName": pfield,
                                  "fieldValue": prompt, "description": "prompt"})

        # 参考图注入
        refs = dyn.get("reference_images") or ctx.get("reference_images") or []
        if isinstance(refs, str):
            refs = [refs]
        refs = [r for r in refs if str(r or "").strip()]
        if refs:
            img_ids_raw = str(_pick(ctx, dyn, "image_node_ids", "") or "").strip()
            if not img_ids_raw:
                raise ValueError("已挂参考图但未配置 image_node_ids（逗号分隔的图像节点 ID，如 6,7）")
            img_ids = [s.strip() for s in img_ids_raw.split(",") if s.strip()]
            if len(refs) > len(img_ids):
                raise ValueError(f"参考图 {len(refs)} 张多于 image_node_ids 节点数 {len(img_ids)}，请补全节点 ID")
            ifield = str(_pick(ctx, dyn, "image_field_name", "image") or "image").strip() or "image"
            for i, (val, nid) in enumerate(zip(refs, img_ids)):
                uploaded = await _upload(client, api_key, val, i)
                if uploaded:
                    node_list.append({"nodeId": nid, "fieldName": ifield,
                                      "fieldValue": uploaded, "description": f"image{i + 1}"})

        body = {
            "addMetadata": _to_bool(_pick(ctx, dyn, "add_metadata", False), False),
            "nodeInfoList": node_list,
            "instanceType": instance_type,
            "usePersonalQueue": "true" if _to_bool(_pick(ctx, dyn, "use_personal_queue", False), False) else "false",
        }
        run_url = f"{API_BASE}/run/workflow/{workflow_id}"
        r = await client.post(run_url, headers=headers, json=body)
        if r.status_code >= 400:
            raise RuntimeError(f"提交失败({r.status_code}): {r.text[:300]}")
        rj = r.json() or {}
        new_id = str(rj.get("taskId") or "").strip()
        status = str(rj.get("status") or "SUBMITTED").upper()
        if not new_id:
            raise RuntimeError(f"未返回 taskId: {str(rj)[:300]}")
        if status in ("FAILED", "CANCEL", "CANCELLED"):
            raise RuntimeError(f"任务失败({status}): {str(rj.get('errorMessage') or rj.get('errorCode') or '')[:300]}")
        return {"url": None, "task_id": new_id, "status": status}
