import httpx
import base64
import json
import re

API_BASE = "https://www.runninghub.ai/openapi/v2"
QUERY_URL = API_BASE + "/query"
UPLOAD_URL = API_BASE + "/media/upload/binary"
WORKFLOW_ID = "2103527148329140225"
NON_TERMINAL = ("CREATE", "QUEUED", "RUNNING", "PENDING", "SUBMITTED")
VIDEO_TYPES = ("mp4", "webm", "mov", "mkv", "avi")
RES_MAP = {
    "480p竖": (480, 854),
    "768p竖": (768, 1366),
    "480p横": (854, 480),
    "768p横": (1366, 768),
}
PURE_PLACEHOLDER = re.compile(r"\s*\{\{(\w+)\}\}\s*")


def _pick(ctx, dyn, key, default=None):
    v = ctx.get(key)
    if v is None or (isinstance(v, str) and not v.strip()):
        v = dyn.get(key) if dyn else None
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return v


def _pick_url(results):
    """视频源：优先视频文件输出，兜底首项 URL"""
    fallback = None
    for item in results:
        if not isinstance(item, dict):
            continue
        url = str(item.get("url") or "").strip()
        if not url:
            continue
        ot = str(item.get("outputType") or "").lower()
        if not fallback:
            fallback = url
        if ot in VIDEO_TYPES or ".mp4" in url.lower() or ".webm" in url.lower():
            return url
    return fallback


def _friendly_submit_error(http_status, payload):
    """RunningHub 提交错误 → 人话引导"""
    text = payload if isinstance(payload, str) else str(payload)
    code = ""
    msg = ""
    if isinstance(payload, dict):
        code = str(payload.get("errorCode") or "")
        msg = str(payload.get("errorMessage") or "")
    blob = f"{http_status} {code} {msg} {text}".lower()
    if "421" in blob or "queue limit" in blob:
        return ("RunningHub API 队列已满(421)：该账号同时排队/运行的任务数达到上限。"
                "请等现有任务完成后再提交，多个镜头改为逐个串行提交，勿同时并发。")
    if "803" in blob or "node_info_mismatch" in blob:
        return f"节点映射不匹配(803)：请检查参数列表里的 nodeId/fieldName 是否与工作流一致。{msg[:200]}"
    if "apikey_invalid" in blob:
        return f"工作流未在网页端成功跑过一次或 Key 无效：{msg[:200]}"
    return f"提交失败({http_status}): {text[:300]}"


async def _upload(client, api_key, value, idx):
    """图片三态归一：RunningHub 文件名透传 / data URI 解码上传 / http(s) 取字节上传"""
    v = str(value or "").strip()
    if not v or v == "None":
        return None
    if not (v.startswith("data:") or v.startswith("http")):
        return v
    if v.startswith("data:"):
        raw = base64.b64decode(v.split(",", 1)[1])
        fname = f"image{idx}.png"
        ctype = "image/png"
    else:
        resp = await client.get(v, timeout=120)
        if resp.status_code >= 400:
            raise RuntimeError(f"图片{idx}下载失败({resp.status_code}): {v[:120]}")
        raw = resp.content
        ctype = resp.headers.get("content-type", "image/png").split(";")[0] or "image/png"
        ext = ctype.split("/")[-1].replace("jpeg", "jpg")
        fname = f"image{idx}.{ext}"
    # 上传只能 Bearer 头：带 Content-Type: application/json 会破坏 multipart 边界
    r = await client.post(
        UPLOAD_URL,
        headers={"Authorization": f"Bearer {api_key}"},
        files={"file": (fname, raw, ctype)},
        timeout=300,
    )
    j = r.json() if r.content else {}
    if not isinstance(j, dict) or j.get("code") != 0:
        raise RuntimeError(f"图片{idx}上传失败: {(j.get('message') if isinstance(j, dict) else '') or str(j)[:300]}")
    d = j.get("data") or {}
    return d.get("download_url") or d.get("fileName")


async def generate(ctx, api):
    dyn = ctx.get("dynamic_inputs") or {}
    api_key = str(ctx.get("api_key") or "").strip()
    if not api_key and isinstance(api, dict) and callable(api.get("get_api_key")):
