    prompt = str(ctx.get("prompt") or dyn.get("prompt") or "").strip()

    async with httpx.AsyncClient(timeout=600) as client:
        # —— 查询分支：单次秒回，绝不 sleep 轮询 ——
        if task_id and not prompt:
            q = await client.post(QUERY_URL, headers=headers, json={"taskId": task_id})
            if q.status_code >= 400:
                raise RuntimeError(f"查询失败({q.status_code}): {q.text[:300]}")
            qj = q.json() or {}
            status = str(qj.get("status") or "").upper()
            if status in NON_TERMINAL:
                return {"video_url": None, "task_id": task_id, "status": status or "RUNNING"}
            if status == "SUCCESS":
                url = _pick_url(qj.get("results") or [])
                if not url:
                    raise RuntimeError(f"任务成功但无结果URL: {str(qj)[:300]}")
                return {"video_url": url}
            err = str(qj.get("errorMessage") or "") or str(qj.get("errorCode") or "")
            raise RuntimeError(f"任务失败({status or 'FAILED'}): {err[:300]}")

        # —— 提交分支：基础参数 = 时长 / 分辨率 / 参数列表 ——
        try:
            duration = int(float(_pick(ctx, dyn, "duration", 5)))
        except Exception:
            duration = 5
        duration = max(1, min(duration, 30))

        resolution = str(_pick(ctx, dyn, "resolution", "768p竖")).strip()
        if resolution not in RES_MAP:
            resolution = "768p竖"
        width, height = RES_MAP[resolution]

        instance_type = str(_pick(ctx, dyn, "instance_type", "default")).strip() or "default"
        if instance_type not in ("default", "plus", "ultra"):
            instance_type = "default"

        # 参数列表（nodeInfoList）：支持 {{prompt}} {{duration}} {{resolution}} {{width}} {{height}}
        #                        {{first_frame}} {{image_1..N}} 占位符；未配置 = 跑工作流默认值
        node_list = []
        raw_nl = str(_pick(ctx, dyn, "node_info_list", "") or "").strip()
        if raw_nl:
            try:
                parsed = json.loads(raw_nl)
            except Exception:
                raise ValueError('参数列表需为合法 JSON 数组，如 [{"nodeId":"28","fieldName":"text","fieldValue":"{{prompt}}"}]')
            if not isinstance(parsed, list):
                raise ValueError("参数列表需为 JSON 数组（list）")
            node_list = [n for n in parsed if isinstance(n, dict)]

        # 图片池（懒上传：只在占位符真正用到时才上传）
        images = []
        ff = dyn.get("first_frame") or ctx.get("first_frame")
        if ff and str(ff).strip():
            images.append(ff)
        more = dyn.get("reference_images") or ctx.get("reference_images") or []
        if isinstance(more, str):
            more = [more]
        images.extend([r for r in more if str(r or "").strip()])
        img_cache = {}

        async def _img_value(i):
            if i not in img_cache:
                if i >= len(images):
                    return None
                img_cache[i] = await _upload(client, api_key, images[i], i)
            return img_cache[i]

        async def _render(v):
            if not isinstance(v, str) or "{{" not in v:
                return v
            m = PURE_PLACEHOLDER.fullmatch(v)
            # 纯数值占位符保留原生类型（ComfyUI int 节点不接受字符串）
            if m and m.group(1) in ("duration", "width", "height"):
                return {"duration": duration, "width": width, "height": height}[m.group(1)]
            s = v
            s = s.replace("{{prompt}}", prompt)
            s = s.replace("{{duration}}", str(duration))
            s = s.replace("{{resolution}}", resolution)
            s = s.replace("{{width}}", str(width))
            s = s.replace("{{height}}", str(height))
            if "{{first_frame}}" in s:
                val = await _img_value(0)
                s = s.replace("{{first_frame}}", str(val or ""))
            for i in range(1, 10):
                token = "{{image_%d}}" % i
                if token in s:
                    val = await _img_value(i)
                    s = s.replace(token, str(val or ""))
            return s

        for node in node_list:
            if "fieldValue" in node:
                node["fieldValue"] = await _render(node["fieldValue"])

        body = {
            "addMetadata": False,
            "nodeInfoList": node_list,
            "instanceType": instance_type,
            "usePersonalQueue": "false",
        }
        r = await client.post(f"{API_BASE}/run/workflow/{WORKFLOW_ID}", headers=headers, json=body)
        rj = {}
        if r.content:
            try:
                rj = r.json() or {}
            except Exception:
                rj = {}
        if r.status_code >= 400 or not str(rj.get("taskId") or "").strip():
            raise RuntimeError(_friendly_submit_error(r.status_code, rj if rj else r.text))
        new_id = str(rj.get("taskId") or "").strip()
        status = str(rj.get("status") or "SUBMITTED").upper()
        if status in ("FAILED", "CANCEL", "CANCELLED"):
            raise RuntimeError(f"任务失败({status}): {str(rj.get('errorMessage') or rj.get('errorCode') or '')[:300]}")
        return {"video_url": None, "task_id": new_id, "status": status}
